const KPD_COL = ['#2F6FD6', '#E07A1F', '#2E9E5B', '#B04FC2'];
const kpdName = el => partMean(el) || (RAD_HINT[el] && RAD_HINT[el][0]) || '';
/** one line that ties the pictures to the meaning */
function kpdStory(k) {
  const og = k.og || {}, pt = k.pt || [], m = k.mean[0] || '';
  if (og.t === 'S' && og.sem) {
    const sm = kpdName(og.sem) || og.h || '', snd = k.on[0] ? kata2hira(k.on[0]) : '';
    return `${og.sem}${sm ? ` (${sm})` : ''} says what it’s about${og.pho ? `; ${og.pho} lends its sound${snd ? `, so it’s read ${snd}` : ''}` : ''} → ${m}.`;
  }
  if (og.h) return `${og.h.replace(/;[^;]*pronunciation.*$/i, '').replace(/[.;]\s*$/, '')} → ${m}.`;
  return `${pt.map(p => `${p[0]}${kpdName(p[0]) ? ` (${kpdName(p[0])})` : ''}`).join(' + ')} → ${m}.`;
}
/** the card: coloured kanji = picture + picture, and the story */
function kpdCard(k) {
  const pt = k.pt || []; if (pt.length < 2) return '';
  return `<div class="kpd" data-kpd="${esc(k.k)}">
    <div class="kpd-eq"><div class="kpd-k"><svg viewBox="0 0 109 109" class="kpd-svg" aria-hidden="true"></svg><span class="kpd-fb jp">${esc(k.k)}</span></div>
      <i class="kpd-op">=</i>${pt.map((p, i) => `${i ? '<i class="kpd-op">+</i>' : ''}<button class="kpd-p" style="--pc:${KPD_COL[i % KPD_COL.length]}" ${KMAP[p[0]] ? `data-open="k:${esc(p[0])}"` : 'tabindex="-1"'}><span class="kpd-pic" aria-hidden="true">${PART_PIC[p[0]] || ''}</span><b class="jp">${esc(p[0])}</b><span>${esc(kpdName(p[0]) || '')}</span></button>`).join('')}</div>
    <p class="kpd-s">${esc(kpdStory(k))}</p></div>`;
}
/** colour each stroke by its part once the stroke data is in */
function kpdHydrate(root) {
  root.querySelectorAll('.kpd[data-kpd]:not([data-done])').forEach(el => {
    el.dataset.done = 1; const c = el.dataset.kpd, k = KMAP[c]; if (!k || DATA.mode !== 'full') return;
    load('strokes', k.lvl).then(obj => {
      const sd = obj && obj[c]; if (!sd || !sd.g) return;
      const svg = el.querySelector('.kpd-svg');
      svg.innerHTML = sd.d.map((d, i) => `<path d="${d}" fill="none" stroke="${KPD_COL[sd.g[i] % KPD_COL.length]}" stroke-width="4.2" stroke-linecap="round" stroke-linejoin="round"/>`).join('');
      el.classList.add('drawn');
    }).catch(() => {});
  });
}

